package com.summitsky.controller;
import com.summitsky.service.WeatherException; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.servlet.mvc.support.RedirectAttributes; import org.springframework.ui.Model;
import java.time.Instant; import java.util.Map;
@ControllerAdvice public class GlobalExceptionHandler {
 @ExceptionHandler({org.springframework.web.method.annotation.HandlerMethodValidationException.class, org.springframework.web.bind.MethodArgumentNotValidException.class}) public Object validation(Exception e,jakarta.servlet.http.HttpServletRequest request,Model model){if(request.getRequestURI().startsWith("/api/"))return ResponseEntity.badRequest().body(Map.of("timestamp",Instant.now(),"status",400,"error","Check the submitted values and try again."));model.addAttribute("error","Check the submitted values and try again.");return "error";}
 @ExceptionHandler(WeatherException.class) public Object weather(WeatherException e, jakarta.servlet.http.HttpServletRequest request, Model model){if(request.getRequestURI().startsWith("/api/")) return ResponseEntity.status(e.status()).body(Map.of("timestamp",Instant.now(),"status",e.status(),"error",e.getMessage())); model.addAttribute("error",e.getMessage());model.addAttribute("city",request.getParameter("city"));return "error";}
 @ExceptionHandler(IllegalArgumentException.class) public Object invalid(IllegalArgumentException e,jakarta.servlet.http.HttpServletRequest request,Model model){if(request.getRequestURI().startsWith("/api/"))return ResponseEntity.badRequest().body(Map.of("status",400,"error",e.getMessage()));model.addAttribute("error",e.getMessage());model.addAttribute("city",request.getParameter("city"));return "error";}
 @ExceptionHandler(Exception.class) public Object other(Exception e,jakarta.servlet.http.HttpServletRequest request,Model model){if(request.getRequestURI().startsWith("/api/"))return ResponseEntity.status(500).body(Map.of("status",500,"error","The request could not be completed."));model.addAttribute("error","The request could not be completed. Please try again.");return "error";}
}
